    spi_master dut (
        .clk(clk),
        .data_in(data_in),
        .miso(miso),
        .reset(reset),
        .start(start),
        .cs(cs),
        .data_out(data_out),
        .done(done),
        .mosi(mosi),
        .sclk(sclk)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

    begin
        reset = 1;
        start = 0;
        data_in = 8'h00;
        miso = 0;
        repeat(2) @(posedge clk);
        reset = 0;
        repeat(2) @(posedge clk);
    end
        endtask
    task simulate_slave;

        input [7:0] data_to_send;
        integer i;
        begin

            wait(cs == 0);
            for (i = 7; i >= 0; i = i - 1) begin


