        wait(done == 1);


        #1;



        check_outputs(1'b1, 8'h00, 1'b1, 1'b1, 1'b0);
    end
        endtask

    task testcase004;

    begin
        test_num = test_num + 1;
        $display("\nTestcase %0d: Transfer 0x12, Expecting 0x34 back", test_num);
        reset_dut();

        data_in = 8'h12;
        start = 1;

        fork
            begin
                @(posedge clk);
