                         expected_cs, expected_data_out, expected_done, expected_mosi, expected_sclk);
                $display("  Got:      cs=%b, data_out=%h, done=%b, mosi=%b, sclk=%b",
                         cs, data_out, done, mosi, sclk);
                fail_count = fail_count + 1;
            end
