        if (counter >= divider) begin
            clk_out <= ~clk_out;
            counter <= 0;
        end
    end

    always @(fractional_value) begin
        divider <= (1 << fractional_value[3:0]); // adjust divider based on fractional value (simplified)
    end
endmodule

