module crc_generator (  
    input clk,  
    input reset,  
    input [31:0] data_in,  
    input [31:0] polynomial,  
    output reg [31:0] crc_out  
);  
    reg [31:0] crc;  
    integer i;  

    always @(posedge clk or posedge reset) begin  
        if (reset)  
            crc <= 32'hFFFFFFFF;  
        else begin  
            crc = crc ^ data_in;  
            for (i = 0; i < 32; i = i + 1) begin  
                if (crc[31])  
                    crc = (crc << 1) ^ polynomial;  
                else  
                    crc = crc << 1;  
            end  
        end  
    end  

    always @(posedge clk) begin  
        crc_out <= crc;  
    end  
endmodule

