module viterbi_decoder (
    input clk,
    input reset,
    input [1:0] encoded_input,
    input valid_input,
    output reg [1:0] decoded_output,
    output reg valid_output
);

    reg [2:0] state;
    reg [2:0] next_state;

    // State encoding
    localparam S0 = 3'b000, S1 = 3'b001, S2 = 3'b010, S3 = 3'b011,
               S4 = 3'b100, S5 = 3'b101, S6 = 3'b110, S7 = 3'b111;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= S0;
            valid_output <= 0;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            S0: begin
                if (valid_input) begin
                    if (encoded_input == 2'b00) begin
                        next_state = S0;
                        decoded_output = 2'b00;
                    end else if (encoded_input == 2'b01) begin
                        next_state = S1;
                        decoded_output = 2'b01;
                    end else if (encoded_input == 2'b10) begin
                        next_state = S2;
                        decoded_output = 2'b10;
                    end else begin
                        next_state = S3;
                        decoded_output = 2'b11;
                    end
                end else begin
                    next_state = S0;
                    decoded_output = 2'b00;
                end
                valid_output = valid_input;
            end
            default: begin
                next_state = S0;
                decoded_output = 2'b00;
                valid_output = 0;
            end
        endcase
    end
endmodule

