module watchdog_timer(
    input clk,
    input rst,
    output reg timeout
);
    parameter TIMEOUT_LIMIT = 4'd10; // Adjust the timeout period as needed
    reg [3:0] counter;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 4'b0000;
            timeout <= 1'b0;
        end else begin
            if (counter < TIMEOUT_LIMIT) begin
                counter <= counter + 1;
                timeout <= 1'b0;
            end else begin
                timeout <= 1'b1; // Trigger timeout if limit reached
            end
        end
    end
endmodule

