code:
module uart_transmitter (  
    input clk,  
    input [7:0] data_in,  
    input transmit_en,  
    output reg tx,  
    output reg busy  
);  
    reg [3:0] bit_index;  
    reg [10:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit  
    parameter IDLE = 2'b00, START = 2'b01, DATA = 2'b10, STOP = 2'b11;  
    reg [1:0] state;  

    always @(posedge clk) begin  
        case (state)  
            IDLE: begin  
                busy <= 0;  
                if (transmit_en) begin  
                    shift_reg <= {1'b1, data_in, 1'b0}; // start with a start bit (0)  
                    bit_index <= 0;  
                    state <= START;  
                    busy <= 1;  
                end  
            end  
            START: begin  
                tx <= 0; // start bit is 0  
                state <= DATA;  
            end  
            DATA: begin  
                tx <= shift_reg[bit_index + 1]; // transmit the next bit  
                if (bit_index < 8)  
                    bit_index <= bit_index + 1;  
                else begin  
                    bit_index <= 0;  
                    state <= STOP;  
                end  
            end  
            STOP: begin  
                tx <= 1; // stop bit is 1  
                busy <= 0;  
                state <= IDLE;  
            end  
            default: state <= IDLE;  
        endcase  
    end  
endmodule

