module dma_controller (  
    input clk,  
    input reset,  
    input start,  
    input [7:0] src_addr,  
    input [7:0] dest_addr,  
    input [7:0] data_in,  
    output reg [7:0] data_out,  
    output reg busy,  
    output reg done  
);  

    reg [2:0] state;  
    reg [2:0] transfer_count;  

    parameter IDLE = 3'b000;  
    parameter TRANSFER = 3'b001;  
    parameter DONE = 3'b010;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            busy <= 0;  
            done <= 0;  
            transfer_count <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start) begin  
                        busy <= 1;  
                        transfer_count <= 0;  
                        state <= TRANSFER;  
                    end  
                end  
                TRANSFER: begin  
                    if (transfer_count < 5) begin  
                        data_out <= data_in;  
                        transfer_count <= transfer_count + 1;  
                    end else begin  
                        state <= DONE;  
                    end  
                end  
                DONE: begin  
                    busy <= 0;  
                    done <= 1;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

