    always @(posedge clk or posedge rst) begin
        if (rst) begin
            top <= 3'b000;
            is_empty <= 1;
            is_full <= 0;
        end else begin
            if (push && !is_full) begin
                stack[top] <= data_in;
                top <= top + 1;
            end
            if (pop && !is_empty) begin
                top <= top - 1;
                data_out <= stack[top];
            end
            is_empty <= (top == 0);
            is_full <= (top == 8);
        end
    end
endmodule

