module encoder_4to2 (  
    input wire [3:0] in,  
    input wire enable,  
    output reg [1:0] out,  
    output reg valid  
);  
    always @(*) begin  
        if (!enable) begin  
            out = 2'b00;  
            valid = 0;  
        end else begin  
            case (in)  
                4'b0000: begin  
                    out = 2'b00;  
                    valid = 0;  
                end  
                4'b0001: begin  
                    out = 2'b00;  
                    valid = 1;  
                end  
                4'b0010: begin  
                    out = 2'b01;  
                    valid = 1;  
                end  
                4'b0100: begin  
                    out = 2'b10;  
                    valid = 1;  
                end  
                4'b1000: begin  
                    out = 2'b11;  
                    valid = 1;  
                end  
                default: begin  
                    out = 2'b00;  
                    valid = 0;  
                end  
            endcase  
        end  
    end  
endmodule

module otsu_thresholding (  
    input [7:0] pixel_value,  
    input [7:0] threshold,  
    output reg binary_output  
);  

always @(*) begin  
