module uart_tx (  
    input wire clk,  
    input wire rst,  
    input wire start,  
    input wire [7:0] data_in,  
    output reg tx,  
    output reg busy  
);  
    parameter BAUD_RATE = 9600;  
    parameter CLOCK_FREQ = 50000000;  
    localparam BIT_TIME = CLOCK_FREQ / BAUD_RATE;  
    reg [3:0] state;  
    reg [7:0] shift_reg;  
    reg [12:0] bit_counter;  

    localparam IDLE = 4'b0000;  
    localparam START_BIT = 4'b0001;  
    localparam DATA_BITS = 4'b0010;  
    localparam STOP_BIT = 4'b0011;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            tx <= 1;  
            busy <= 0;  
            bit_counter <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start) begin  
                        shift_reg <= data_in;  
                        state <= START_BIT;  
                        busy <= 1;  
                    end  
                end  
                START_BIT: begin  
                    if (bit_counter < BIT_TIME - 1) begin  
                        bit_counter <= bit_counter + 1;  
                    end else begin  
                        tx <= 0;  
                        bit_counter <= 0;  
                        state <= DATA_BITS;  
                    end  
                end  
                DATA_BITS: begin  
                    if (bit_counter < BIT_TIME - 1) begin  
                        bit_counter <= bit_counter + 1;  
                    end else begin  
                        tx <= shift_reg[0];  
                        shift_reg <= {1'b0, shift_reg[7:1]};  
                        bit_counter <= 0;  
                        if (shift_reg == 0) begin  
                            state <= STOP_BIT;  
                        end  
                    end  
                end  
                STOP_BIT: begin  
                    if (bit_counter < BIT_TIME - 1) begin  
                        bit_counter <= bit_counter + 1;  
                    end else begin  
                        tx <= 1;  
                        state <= IDLE;  
                        busy <= 0;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

module bilinear_interpolation(
    input [7:0] P00,
    input [7:0] P01,
    input [7:0] P10,
    input [7:0] P11,
    input [7:0] x, // x coordinate (0-255)
    input [7:0] y, // y coordinate (0-255)
    output [7:0] P_out
);
    wire [15:0] x_weight, y_weight;
    wire [15:0] P0, P1, P_out_temp;

    assign x_weight = {8'b0, x}; // Extend x to 16 bits
    assign y_weight = {8'b0, y}; // Extend y to 16 bits

    // Calculate the intermediate pixel values
    assign P0 = (P00 * (256 - x_weight) + P01 * x_weight) >> 8; // Interpolate along x
    assign P1 = (P10 * (256 - x_weight) + P11 * x_weight) >> 8; // Interpolate along x

    // Calculate final output
    assign P_out = (P0 * (256 - y_weight) + P1 * y_weight) >> 8; // Interpolate along y

endmodule

module spi_controller (
    input wire clk,
    input wire start,
    input wire [7:0] data_in,
    output reg mosi,
    output reg busy
);
    reg [2:0] bit_index;

    always @(posedge clk) begin
        if (start) begin
            busy <= 1'b1;
            bit_index <= 3'b000;
        end else if (busy) begin
            if (bit_index < 3'b111) begin
                mosi <= data_in[7 - bit_index];
                bit_index <= bit_index + 1;
            end else begin
                busy <= 1'b0; // Transmission finished
            end
        end
    end
endmodule

