module sd_card_controller (
    input wire clk,
    input wire start_init,
    output reg init_done,
    output reg reading_data,
    output reg [1:0] state // 00: idle, 01: initializing, 10: reading, 11: error
);
    // State encoding
    parameter IDLE = 2'b00;
    parameter INITIALIZING = 2'b01;
    parameter READING = 2'b10;

    // State variable
    reg [1:0] current_state, next_state;

    // State transition logic
    always @(posedge clk) begin
        current_state <= next_state;
    end

    // Next state logic and output
    always @(*) begin
        case (current_state)
            IDLE: begin
                init_done = 0;
                reading_data = 0;
                if (start_init) begin
                    next_state = INITIALIZING;
                end else begin
                    next_state = IDLE;
                end
            end
            INITIALIZING: begin
                init_done = 0;
                reading_data = 0;
                // Simulate initialization time
                next_state = READING; // Move to reading after initialization
            end
            READING: begin
                init_done = 1;
                reading_data = 1;
                next_state = IDLE; // Go back to idle after reading
            end
            default: begin
                init_done = 0;
                reading_data = 0;
                next_state = IDLE;
            end
        endcase
    end

    // Initial state
    initial begin
        current_state = IDLE;
        init_done = 0;
        reading_data = 0;
    end
endmodule

