    aes_256 dut (
        .clk(clk),
        .enable(enable),
        .key(key),
        .plaintext(plaintext),
        .reset(reset),
        .ciphertext(ciphertext),
        .done(done)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            reset = 1;
            enable = 0;
            key = 256'h0;
            plaintext = 256'h0;
            @(posedge clk);
            #2 reset = 0;
            @(posedge clk);
