            plaintext = 256'h0;
            key       = 256'h0;
            enable    = 1;

            @(posedge clk);
            enable = 0;


            wait(done === 1'b1);
            @(posedge clk);


            #1;



            check_outputs(256'hDC95C078A24089895397CEB4B3428801DC95C078A24089895397CEB4B3428801, 1'b1);
