module qam_modulator (
    input clk,
    input rst,
    input [3:0] I,
    input [3:0] Q,
    output reg [7:0] modulated_signal
);
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            modulated_signal <= 8'b00000000;
        end else begin
            // Combine I and Q into the modulated signal
            modulated_signal <= {I, Q};
        end
    end
endmodule
